ALTER TABLE public.packages ADD COLUMN IF NOT EXISTS circuit_id uuid REFERENCES public.packages(id), ADD COLUMN IF NOT EXISTS economy_price numeric, ADD COLUMN IF NOT EXISTS vip_price numeric, ADD COLUMN IF NOT EXISTS group_price_min numeric, ADD COLUMN IF NOT EXISTS group_price_max numeric, ADD COLUMN IF NOT EXISTS group_people_min integer DEFAULT 2, ADD COLUMN IF NOT EXISTS group_people_max integer DEFAULT 5, ADD COLUMN IF NOT EXISTS currency text DEFAULT 'USD'; ALTER TABLE public.packages ADD CONSTRAINT package_tariffs_valid CHECK ((economy_price IS NULL OR economy_price >= 0) AND (vip_price IS NULL OR vip_price >= 0) AND (group_price_min IS NULL OR group_price_min >= 0) AND (group_price_max IS NULL OR group_price_max >= group_price_min) AND (group_people_min >= 1 AND group_people_max >= group_people_min) AND (circuit_id IS NULL OR circuit_id <> id));